function getLang() {
  try { return localStorage.getItem("hf-lang") || "en"; } catch (e) { return "en"; }
}
function setLangAndReload(lang) {
  try { localStorage.setItem("hf-lang", lang); } catch (e) {}
  window.location.reload();
}
