function money(n) {
  return (Number(n) || 0).toLocaleString("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });
}
function itemsTotal(items) { return items.reduce((s, i) => s + (Number(i.amount) || 0), 0); }
function invoicePaid(inv) { return inv.payments.reduce((s, p) => s + (Number(p.amount) || 0), 0); }
function invoiceStatus(inv) {
  const bal = itemsTotal(inv.items) - invoicePaid(inv);
  if (bal <= 0) return "Paid";
  if (invoicePaid(inv) > 0) return "Partial";
  return "Unpaid";
}
function todayStr() {
  return new Date().toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

// ---- Location + media helpers ----
const DEFAULT_GEOFENCE_METERS = 150;

function haversineMeters(lat1, lng1, lat2, lng2) {
  const R = 6371000;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function getCurrentPosition() {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) { reject(new Error("Location not supported on this device")); return; }
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      (err) => reject(err),
      { enableHighAccuracy: true, timeout: 15000 }
    );
  });
}

function formatDateTime(dt) {
  if (!dt) return "";
  const d = new Date(dt);
  if (isNaN(d)) return dt;
  return d.toLocaleString("en-US", { weekday: "short", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
}

async function uploadJobMedia(file, taskId) {
  const ext = file.name.split(".").pop();
  const path = `${taskId}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/job-media/${path}`, {
    method: "POST",
    headers: sbHeaders({ "Content-Type": file.type }),
    body: file,
  });
  if (!res.ok) throw new Error("Upload failed");
  const url = `${SUPABASE_URL}/storage/v1/object/public/job-media/${path}`;
  return { path, url, type: file.type.startsWith("video") ? "video" : "image" };
}

async function deleteJobMedia(path) {
  await fetch(`${SUPABASE_URL}/storage/v1/object/job-media/${path}`, {
    method: "DELETE",
    headers: sbHeaders(),
  });
}

