function formatDateOnly(dt) {
  if (!dt) return "";
  const d = new Date(dt);
  if (isNaN(d)) return dt;
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function isOverdue(dueDate, isPaid) {
  if (!dueDate || isPaid) return false;
  return new Date(dueDate) < new Date(new Date().toDateString());
}

const APP_URL = "https://house-fixed-dashboard-yfgt.vercel.app";

function googleCalendarUrl({ title, description, location, start, finish }) {
  const fmt = (d) => {
    const dt = new Date(d);
    if (isNaN(dt)) return "";
    return dt.toISOString().replace(/[-:]|\.\d{3}/g, "");
  };
  const s = fmt(start);
  const e = fmt(finish || start);
  if (!s) return null;
  const params = new URLSearchParams({
    action: "TEMPLATE",
    text: title || "Job",
    dates: `${s}/${e}`,
    details: description || "",
    location: location || "",
  });
  return `https://calendar.google.com/calendar/render?${params.toString()}`;
}

function AddToCalendarButton({ task }) {
  const url = googleCalendarUrl({
    title: `${task.service} — ${task.customer}`,
    description:
      `House Fixed Inc job for ${task.customer}. Phone: ${task.phone || "n/a"}. Job ID: ${task.id}.\n\n` +
      `Open the job in the app: ${APP_URL}\n\n` +
      `Tip: after adding this to your calendar, tap the event and set a custom notification (e.g. 1 hour before) — Google's quick-add link can't set that automatically.`,
    location: task.address,
    start: task.start,
    finish: task.finish,
  });
  if (!url) return null;
  return (
    <a href={url} target="_blank" rel="noopener noreferrer"
      className="w-full text-xs font-semibold px-3 py-2.5 rounded-sm flex items-center justify-center gap-2" style={{ border: `1px solid ${LINE}`, color: INK }}>
      <CalendarPlus size={14} /> Add to my Google Calendar
    </a>
  );
}

