function titleCaseAddress(s) {
  return s.toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase())
    .replace(/\bSt\b/g, "St").replace(/\bNy\b/g, "NY").replace(/\bUsa\b/gi, "");
}

function cleanNominatimLabel(item) {
  const a = item.address || {};
  const street = [a.house_number, a.road].filter(Boolean).join(" ");
  const city = a.city || a.town || a.village || a.hamlet || "";
  const state = a.state_code || (a.state ? a.state.slice(0, 2).toUpperCase() : "");
  const zip = a.postcode || "";
  const parts = [street, city, [state, zip].filter(Boolean).join(" ")].filter(Boolean);
  return parts.length >= 2 ? parts.join(", ") : item.display_name;
}

// Shared one-shot geocoder — used both by the live-suggestions dropdown while
// typing, and as a fallback lookup (e.g. re-tried automatically when an
// employee starts a job whose address was typed manually and never matched
// a suggestion).
async function geocodeAddressCandidates(text) {
  try {
    const censusRes = await fetch(
      `https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=${encodeURIComponent(text)}&benchmark=Public_AR_Current&format=json`
    );
    const censusData = await censusRes.json();
    const matches = censusData?.result?.addressMatches || [];
    if (matches.length > 0) {
      return matches.map(m => ({ label: titleCaseAddress(m.matchedAddress), lat: m.coordinates.y, lng: m.coordinates.x }));
    }
    const res = await fetch(
      `https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&limit=5&countrycodes=us&q=${encodeURIComponent(text)}`,
      { headers: { "Accept-Language": "en" } }
    );
    const data = await res.json();
    return (data || []).map(item => ({ label: cleanNominatimLabel(item), lat: parseFloat(item.lat), lng: parseFloat(item.lon) }));
  } catch (e) {
    return [];
  }
}

function AddressAutocomplete({ value, onChangeText, onSelect, placeholder }) {
  const [suggestions, setSuggestions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showList, setShowList] = useState(false);
  const [searched, setSearched] = useState(false);
  const debounceRef = useRef(null);

  const search = (text) => {
    onChangeText(text);
    setShowList(true);
    setSearched(false);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (text.trim().length < 5) { setSuggestions([]); return; }
    debounceRef.current = setTimeout(async () => {
      setLoading(true);
      const results = await geocodeAddressCandidates(text);
      setSuggestions(results);
      setSearched(true);
      setLoading(false);
    }, 500);
  };

  // A deliberate, no-timing-race way to search — tap it and the results stay
  // put until you tap one, instead of the live-as-you-type dropdown that can
  // vanish before you get a chance to tap it on a phone.
  const manualSearch = async () => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (!value.trim() || value.trim().length < 5) return;
    setShowList(true);
    setLoading(true);
    setSearched(false);
    const results = await geocodeAddressCandidates(value);
    setSuggestions(results);
    setSearched(true);
    setLoading(false);
  };

  const pick = (item) => {
    onChangeText(item.label);
    onSelect({ address: item.label, lat: item.lat, lng: item.lng });
    setSuggestions([]);
    setShowList(false);
  };

  return (
    <div className="relative">
      <div className="flex items-center gap-2">
        <input
          value={value}
          onChange={(e) => search(e.target.value)}
          onFocus={() => setShowList(true)}
          placeholder={placeholder}
          className="flex-1 px-3 py-2 text-sm rounded-sm outline-none"
          style={{ border: `1px solid ${LINE}`, background: "#fff" }}
        />
        <button type="button" onClick={manualSearch} disabled={loading}
          className="px-3 py-2 rounded-sm flex items-center justify-center shrink-0" style={{ background: AMBER, color: "#fff" }}>
          <Search size={16} />
        </button>
      </div>
      {loading && <div className="text-[10px] mt-1" style={{ color: INK2 }}>Searching…</div>}
      {showList && suggestions.length > 0 && (
        <div className="relative z-20 mt-1 rounded-sm overflow-hidden" style={{ background: "#fff", border: `1px solid ${LINE}`, boxShadow: "0 6px 16px rgba(0,0,0,0.15)" }}>
          {suggestions.map((s, i) => (
            <button
              key={i}
              type="button"
              onClick={() => pick(s)}
              className="w-full text-left px-3 py-2 text-xs flex items-start gap-2"
              style={{ borderBottom: i < suggestions.length - 1 ? `1px solid ${LINE}` : "none", color: INK }}
            >
              <MapPin size={12} className="mt-0.5 shrink-0" color={INK2} />
              {s.label}
            </button>
          ))}
          <button type="button" onClick={() => setShowList(false)} className="w-full text-center px-3 py-1.5 text-[11px]" style={{ color: INK2, background: "#F1EFE8" }}>
            Close
          </button>
        </div>
      )}
      {!loading && searched && showList && suggestions.length === 0 && (
        <div className="relative z-20 mt-1 rounded-sm p-3" style={{ background: "#FCEBEB", border: "1px solid #E8A9A9" }}>
          <p className="text-xs mb-1" style={{ color: "#A32D2D" }}>Couldn't find an exact match for that address.</p>
          <p className="text-[11px]" style={{ color: "#7A2020" }}>Double-check the street number, spelling, and ZIP code, then tap the search button again. The address will still save as typed even without a map match — you can set its exact location later from the Jobs tab, or by standing at the site.</p>
        </div>
      )}
    </div>
  );
}

