function EstimateDetail({ estimate, onConvertToInvoice, onCreateTask, task, onUpdate, employees, onDelete }) {
  const [showTaskForm, setShowTaskForm] = useState(false);
  const total = itemsTotal(estimate.items);
  const deposit = Number(estimate.deposit?.value) || 0;

  const shareText = `Estimate ${estimate.id} — ${estimate.customer}\n${estimate.service}\nTotal: ${money(total)}` +
    (deposit > 0 ? `\nDeposit required to start: ${money(deposit)}` : "") +
    `\n\nHouse Fixed Inc · (845) 482-0672`;

  const handleDownload = () => {
    const doc = buildDocumentPdf({
      docType: "Estimate", id: estimate.id, status: estimate.status,
      customer: estimate.customer, phone: estimate.phone, email: estimate.email, address: estimate.address,
      service: estimate.service, items: estimate.items, createdAt: estimate.createdAt, dueDate: estimate.dueDate,
      deposit: estimate.deposit, preferredMethods: estimate.preferredMethods,
    });
    doc.save(`Estimate-${estimate.id}.pdf`);
  };
  const handleShare = async () => {
    if (navigator.share) { try { await navigator.share({ title: `Estimate ${estimate.id}`, text: shareText }); } catch (e) {} }
    else { try { await navigator.clipboard.writeText(shareText); alert("Estimate summary copied — paste it anywhere to share."); } catch (e) { alert(shareText); } }
  };
  const handleEmail = () => {
    const subject = encodeURIComponent(`Estimate ${estimate.id} from House Fixed Inc`);
    const body = encodeURIComponent(
      `Hi ${estimate.customer},\n\nHere's your estimate for ${estimate.service}:\n\n` +
      estimate.items.map(i => `- ${i.desc}: ${money(i.amount)}`).join("\n") +
      `\n\nTotal: ${money(total)}` +
      (deposit > 0 ? `\n\nA deposit of ${money(deposit)} is required to confirm and schedule this job. The remaining balance is due upon completion.` : "") +
      (estimate.preferredMethods?.length ? `\n\nAccepted payment methods: ${estimate.preferredMethods.join(", ")}` : "") +
      `\n\nThank you,\nHouse Fixed Inc\n(845) 482-0672`
    );
    window.location.href = `mailto:${estimate.email || ""}?subject=${subject}&body=${body}`;
  };

  return (
    <div className="p-4 space-y-4 printable-invoice">
      <style>{`@media print { .no-print { display: none !important; } .printable-invoice { padding: 0 !important; } }`}</style>

      <DocHeader />
      <ContactBlock record={estimate} onSave={(fields) => onUpdate(estimate.id, fields)} />
      <DatesBlock createdAt={estimate.createdAt} dueDate={estimate.dueDate} onSaveDueDate={(d) => onUpdate(estimate.id, { dueDate: d })} isPaid={false} />

      <div className="rounded-sm p-5" style={{ background: "#FFFDF9", border: `1px solid ${LINE}` }}>
        <div className="flex items-start justify-between mb-4 pb-4" style={{ borderBottom: `2px dashed ${LINE}` }}>
          <div>
            <div className="text-[10px] uppercase tracking-widest font-semibold" style={{ color: INK2 }}>Estimate</div>
            <div className="text-lg font-bold font-mono" style={{ color: INK }}>{estimate.id}</div>
          </div>
          <StatusPill status={estimate.status} />
        </div>
        <div className="text-[11px] font-mono uppercase tracking-wider mb-3" style={{ color: AMBER_DARK }}>{estimate.service}</div>
        <div className="space-y-1.5 mb-4">
          {estimate.items.map((it, idx) => (
            <div key={idx} className="flex items-center justify-between text-sm">
              <span style={{ color: INK }}>{it.desc}</span>
              <span className="font-mono" style={{ color: INK }}>{money(it.amount)}</span>
            </div>
          ))}
        </div>
        <div className="flex items-center justify-between pt-3" style={{ borderTop: `1px dashed ${LINE}` }}>
          <span className="text-xs uppercase tracking-wider font-semibold" style={{ color: INK2 }}>Total</span>
          <span className="text-xl font-bold" style={{ color: INK }}>{money(total)}</span>
        </div>
      </div>

      {deposit > 0 && (
        <div className="rounded-sm p-4" style={{ background: "#FAEEDA", border: `1px solid ${AMBER}` }}>
          <div className="text-sm font-bold mb-1" style={{ color: AMBER_DARK }}>{money(deposit)} deposit required</div>
          <p className="text-xs" style={{ color: "#5E3E0E" }}>You need to pay the deposit before we start the job to confirm the job. The remaining balance ({money(total - deposit)}) is due upon completion.</p>
        </div>
      )}

      {estimate.preferredMethods?.length > 0 && (
        <div className="rounded-sm p-4" style={{ background: "#FFFDF9", border: `1px solid ${LINE}` }}>
          <div className="text-[10px] uppercase tracking-wider font-semibold mb-2" style={{ color: INK2 }}>Accepted payment methods</div>
          <div className="flex flex-wrap gap-2">
            {estimate.preferredMethods.map(m => (
              <span key={m} className="text-xs font-semibold px-2.5 py-1 rounded-sm" style={{ background: "#EAF3DE", color: "#3B6D11" }}>{m}</span>
            ))}
          </div>
        </div>
      )}

      <div className="no-print space-y-3">
        {estimate.status !== "Accepted" && (
          <button onClick={() => onConvertToInvoice(estimate)} className="w-full text-xs font-bold uppercase tracking-wider px-3 py-3 rounded-sm flex items-center justify-center gap-2" style={{ background: NAVY, color: "#fff" }}>
            <Receipt size={13} /> Convert to invoice
          </button>
        )}

        {task ? (
          <div className="rounded-sm p-3 flex items-center justify-between" style={{ background: "#E6F1FB", border: `1px solid #85B7EB` }}>
            <div className="text-xs font-semibold" style={{ color: "#0C447C" }}>Scheduled: {task.start} → {task.finish}</div>
            <StatusPill status={task.status} />
          </div>
        ) : showTaskForm ? (
          <TaskForm defaultTitle={`${estimate.customer} · ${estimate.service}`} defaultAddress={estimate.address} onClose={() => setShowTaskForm(false)} hasSourceLocation={estimate.lat != null} employees={employees}
            onCreate={(start, finish, coords, assignedTo, employeePay) => { onCreateTask(estimate, start, finish, coords, assignedTo, employeePay); setShowTaskForm(false); }} />
        ) : (
          <button onClick={() => setShowTaskForm(true)} className="w-full text-xs font-bold uppercase tracking-wider px-3 py-3 rounded-sm flex items-center justify-center gap-2" style={{ background: AMBER, color: "#fff" }}>
            <CalendarPlus size={14} /> Create task / schedule job
          </button>
        )}

        <DocActions onDownload={handleDownload} onShare={handleShare} onEmail={handleEmail} />
        <DeleteButton label="Delete this estimate" onConfirm={() => onDelete(estimate.id)} />
      </div>
    </div>
  );
}

