function JobLocationGate({ task, action, onSuccess, blocked, blockedReason, onLocationResolved }) {
  // action: 'start' | 'finish'
  const [checking, setChecking] = useState(false);
  const [checkingLabel, setCheckingLabel] = useState(t("checkingLocation"));
  const [err, setErr] = useState("");
  const [now, setNow] = useState(Date.now());

  // Re-check every 20s so the button unlocks itself the moment the scheduled time arrives —
  // no need for the employee to refresh or reopen the app.
  useEffect(() => {
    const iv = setInterval(() => setNow(Date.now()), 20000);
    return () => clearInterval(iv);
  }, []);

  const scheduledStart = task.start ? new Date(task.start).getTime() : null;
  const tooEarly = action === "start" && scheduledStart && now < scheduledStart;
  const disabled = checking || tooEarly || blocked;

  const attempt = async () => {
    if (blocked) {
      setErr(blockedReason || "You can't do this yet.");
      return;
    }
    if (tooEarly) {
      setErr(`This job isn't scheduled to start until ${formatDateTime(task.start)}. You can't clock in early.`);
      return;
    }
    setChecking(true); setErr("");
    setCheckingLabel(t("checkingLocation"));

    // If no saved coordinates exist (the search dropdown never matched this
    // address when it was typed), try geocoding the saved address text itself
    // right now — a full address with zip often succeeds even when the live
    // suggestions-while-typing search didn't find it.
    let jobLat = task.lat;
    let jobLng = task.lng;
    if (jobLat == null || jobLng == null) {
      if (!task.address) {
        setErr("No job location set by your manager yet — you can't start/finish until it's added.");
        setChecking(false);
        return;
      }
      setCheckingLabel("Looking up job address…");
      const candidates = await geocodeAddressCandidates(task.address);
      if (candidates.length === 0) {
        setErr("Couldn't match the saved address to a location. Ask your manager to double-check it.");
        setChecking(false);
        return;
      }
      jobLat = candidates[0].lat;
      jobLng = candidates[0].lng;
      if (onLocationResolved) onLocationResolved(jobLat, jobLng);
      setCheckingLabel("Checking your location…");
    }

    try {
      const pos = await getCurrentPosition();
      const dist = haversineMeters(pos.lat, pos.lng, jobLat, jobLng);
      const radius = task.geofenceMeters || DEFAULT_GEOFENCE_METERS;
      if (dist <= radius) {
        onSuccess(pos);
      } else {
        setErr(`You're about ${Math.round(dist)}m from the job site — get within ${radius}m to ${action}.`);
      }
    } catch (e) {
      setErr("Couldn't get your location. Make sure location access is allowed.");
    } finally {
      setChecking(false);
    }
  };

  return (
    <div>
      {blocked && blockedReason && (
        <p className="text-[11px] mb-2 text-center font-semibold" style={{ color: AMBER_DARK }}>{blockedReason}</p>
      )}
      <button onClick={attempt} disabled={disabled}
        className="w-full text-xs font-bold uppercase tracking-wider px-3 py-3 rounded-sm flex items-center justify-center gap-2"
        style={{ background: (tooEarly || blocked) ? LINE : action === "start" ? AMBER : NAVY, color: (tooEarly || blocked) ? INK2 : "#fff" }}>
        {tooEarly ? <Bell size={15} /> : action === "start" ? <PlayCircle size={15} /> : <StopCircle size={15} />}
        {tooEarly
          ? `${t("opens")} ${formatDateTime(task.start)}`
          : blocked ? t("addPhotoVideoFirst")
          : checking ? checkingLabel : action === "start" ? t("startJob") : t("finishJob")}
      </button>
      {err && <p className="text-[11px] mt-2 text-center" style={{ color: "#A32D2D" }}>{err}</p>}
    </div>
  );
}

function EmployeeView({ employee, tasks, setTasks, onLogout }) {
  const myTasks = tasks.filter(t => t.assignedTo === employee.id);
  const [notified, setNotified] = useState({});

  const addMaterial = (taskId, desc, qty) => {
    setTasks(tasks.map(t => t.id === taskId ? { ...t, materials: [...t.materials, { id: "M-" + Date.now(), desc, qty }] } : t));
  };
  const addNote = (taskId, text) => {
    setTasks(tasks.map(t => t.id === taskId ? { ...t, notes: [...t.notes, { id: "N-" + Date.now(), text, author: employee.name, date: todayStr() }] } : t));
  };
  const addMedia = (taskId, item) => {
    setTasks(tasks.map(t => t.id === taskId ? { ...t, media: [...t.media, item] } : t));
  };
  const startJob = (taskId, pos) => {
    setTasks(tasks.map(t => t.id === taskId ? { ...t, status: "In progress", actualStart: { time: new Date().toISOString(), ...pos } } : t));
  };
  const finishJob = (taskId, pos) => {
    setTasks(tasks.map(t => t.id === taskId ? { ...t, status: "Done", actualFinish: { time: new Date().toISOString(), ...pos } } : t));
  };
  const resolveTaskLocation = (taskId, lat, lng) => {
    setTasks(tasks.map(t => t.id === taskId ? { ...t, lat, lng } : t));
  };

  // Best-effort foreground reminder: checks every 30s while this screen is open.
  // NOTE: this only fires while the employee has the app open — real lock-screen
  // reminders need push notifications from a server, which isn't set up.
  useEffect(() => {
    if ("Notification" in window && Notification.permission === "default") {
      Notification.requestPermission();
    }
    const interval = setInterval(() => {
      const now = Date.now();
      myTasks.forEach(t => {
        if (t.status !== "Scheduled" || !t.start || notified[t.id]) return;
        const startTime = new Date(t.start).getTime();
        const minsAway = (startTime - now) / 60000;
        if (minsAway <= 15 && minsAway > -5) {
          setNotified(n => ({ ...n, [t.id]: true }));
          if ("Notification" in window && Notification.permission === "granted") {
            new Notification("Upcoming job", { body: `${t.service} at ${t.address} — ${formatDateTime(t.start)}` });
          }
        }
      });
    }, 30000);
    return () => clearInterval(interval);
  }, [myTasks, notified]);

  return (
    <div className="max-w-sm mx-auto min-h-[640px] flex flex-col" style={{ background: PAPER, fontFamily: "system-ui, sans-serif" }}>
      <TopBar title={`${t("hi")}, ${employee.name.split(" ")[0]}`} right={<div className="flex items-center gap-2"><LanguageToggle dark /><button onClick={onLogout} className="text-white/80"><LogOut size={18} /></button></div>} />
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        <p className="text-xs" style={{ color: INK2 }}>{t("yourJobs")}</p>
        {myTasks.length === 0 && <p className="text-xs text-center py-10" style={{ color: INK2 }}>{t("noJobsAssigned")}</p>}
        {myTasks.map(t => (
          <div key={t.id} className="rounded-sm p-4 space-y-3" style={{ background: "#FFFDF9", border: `1px solid ${LINE}` }}>
            <div className="flex items-start justify-between">
              <div>
                <div className="text-sm font-bold" style={{ color: INK }}>{t.customer}</div>
                <div className="text-[11px] font-mono uppercase tracking-wider mt-0.5" style={{ color: AMBER_DARK }}>{t.service}</div>
              </div>
              <StatusPill status={t.status} />
            </div>
            <div className="space-y-1">
              {t.phone && <div className="flex items-center gap-2 text-xs" style={{ color: INK2 }}><Phone size={12} />{t.phone}</div>}
              {t.address && <div className="flex items-center gap-2 text-xs" style={{ color: INK2 }}><MapPin size={12} />{t.address}</div>}
            </div>
            {t.employeePay != null && (
              <div className="rounded-sm px-3 py-2" style={{ background: "#EAF3DE" }}>
                <span className="text-[10px] uppercase tracking-wider font-semibold" style={{ color: "#3B6D11" }}>{LANG === "es" ? "Te van a pagar" : "You'll be paid"}</span>
                <div className="text-base font-bold" style={{ color: "#3B6D11" }}>{money(t.employeePay)}</div>
              </div>
            )}
            <div className="flex items-center gap-2 text-xs font-semibold" style={{ color: INK }}>
              <Bell size={12} /> {formatDateTime(t.start)} → {formatDateTime(t.finish)}
            </div>
            <AddToCalendarButton task={t} />

            {t.status === "Scheduled" && (
              <>
                <JobLocationGate task={t} action="start" onSuccess={(pos) => startJob(t.id, pos)} onLocationResolved={(lat, lng) => resolveTaskLocation(t.id, lat, lng)} />
                <MaterialsBlock materials={t.materials} onAdd={(desc, qty) => addMaterial(t.id, desc, qty)} />
                <NotesBlock notes={t.notes} onAdd={(text) => addNote(t.id, text)} />
                <MediaBlock media={t.media || []} taskId={t.id} uploaderName={employee.name} canDelete={false}
                  onAdd={(item) => addMedia(t.id, item)} onDelete={() => {}} />
              </>
            )}

            {t.status === "In progress" && (
              <>
                <div className="rounded-sm p-3" style={{ background: "#FAEEDA", border: `1px solid ${AMBER}` }}>
                  <p className="text-[11px] font-semibold" style={{ color: AMBER_DARK }}>{t("addPhotoVideoNote")}</p>
                </div>
                <MaterialsBlock materials={t.materials} onAdd={(desc, qty) => addMaterial(t.id, desc, qty)} />
                <NotesBlock notes={t.notes} onAdd={(text) => addNote(t.id, text)} />
                <MediaBlock media={t.media || []} taskId={t.id} uploaderName={employee.name} canDelete={false}
                  onAdd={(item) => addMedia(t.id, item)} onDelete={() => {}} />
                <JobLocationGate task={t} action="finish" onSuccess={(pos) => finishJob(t.id, pos)} onLocationResolved={(lat, lng) => resolveTaskLocation(t.id, lat, lng)}
                  blocked={!(t.media || []).some(m => m.type === "image") || !(t.media || []).some(m => m.type === "video")}
                  blockedReason={t("addPhotoVideoNote")} />
              </>
            )}
            {t.status === "Done" && (
              <>
                <div className="flex items-center gap-1 text-xs font-semibold" style={{ color: "#3B6D11" }}>
                  <CheckCircle2 size={14} /> {t("completed")}
                </div>
                <MaterialsBlock materials={t.materials} onAdd={(desc, qty) => addMaterial(t.id, desc, qty)} />
                <NotesBlock notes={t.notes} onAdd={(text) => addNote(t.id, text)} />
                <MediaBlock media={t.media || []} taskId={t.id} uploaderName={employee.name} canDelete={false}
                  onAdd={(item) => addMedia(t.id, item)} onDelete={() => {}} />
              </>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

