// Set once a real user (owner or employee) signs in below. Every Supabase call after
// that point authenticates AS that person, which is what lets the "authenticated only"
// database rules actually tell people apart, instead of everyone sharing one open key.
let currentAccessToken = null;

function sbHeaders(extra = {}) {
  return {
    apikey: SUPABASE_ANON_KEY,
    Authorization: `Bearer ${currentAccessToken || SUPABASE_ANON_KEY}`,
    "Content-Type": "application/json",
    ...extra,
  };
}

async function signInWithPassword(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
    method: "POST",
    headers: { apikey: SUPABASE_ANON_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Invalid email or password.");
  currentAccessToken = data.access_token;
  return { email: data.user?.email || email, refreshToken: data.refresh_token };
}

async function refreshSession(refreshToken) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`, {
    method: "POST",
    headers: { apikey: SUPABASE_ANON_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ refresh_token: refreshToken }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Session expired — please log in with your password.");
  currentAccessToken = data.access_token;
  return { email: data.user?.email, refreshToken: data.refresh_token };
}

function signOutLocal() {
  currentAccessToken = null;
}

// ---- Face ID / fingerprint (WebAuthn) helpers ----
// Honest limitation: without a backend server, this can't be a fully
// server-verified passwordless login. What it genuinely is: your device's
// own Face ID/fingerprint hardware gates access to a saved login session
// stored in this browser only, on this device. It's a real convenience lock
// using real biometric hardware — just not bank-grade cryptographic auth.
const BIOMETRIC_KEY = "hf-biometric-lock-v1";

function bufToB64Url(buf) {
  const bytes = new Uint8Array(buf);
  let str = "";
  for (let i = 0; i < bytes.length; i++) str += String.fromCharCode(bytes[i]);
  return btoa(str).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function b64UrlToBuf(b64url) {
  const b64 = b64url.replace(/-/g, "+").replace(/_/g, "/");
  const raw = atob(b64);
  const buf = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) buf[i] = raw.charCodeAt(i);
  return buf.buffer;
}

async function isBiometricAvailable() {
  if (!window.PublicKeyCredential || !navigator.credentials) return false;
  try { return await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable(); } catch (e) { return false; }
}

async function registerBiometric(email) {
  const challenge = crypto.getRandomValues(new Uint8Array(32));
  const userId = crypto.getRandomValues(new Uint8Array(16));
  const cred = await navigator.credentials.create({
    publicKey: {
      challenge,
      rp: { name: "House Fixed Console" },
      user: { id: userId, name: email, displayName: email },
      pubKeyCredParams: [{ alg: -7, type: "public-key" }, { alg: -257, type: "public-key" }],
      authenticatorSelection: { authenticatorAttachment: "platform", userVerification: "required" },
      timeout: 60000,
    },
  });
  return bufToB64Url(cred.rawId);
}

async function verifyBiometric(credentialIdB64) {
  const challenge = crypto.getRandomValues(new Uint8Array(32));
  const assertion = await navigator.credentials.get({
    publicKey: {
      challenge,
      allowCredentials: [{ id: b64UrlToBuf(credentialIdB64), type: "public-key" }],
      userVerification: "required",
      timeout: 60000,
    },
  });
  return !!assertion;
}

function saveBiometricLock(record) {
  try { localStorage.setItem(BIOMETRIC_KEY, JSON.stringify(record)); } catch (e) {}
}
function loadBiometricLock() {
  try { const raw = localStorage.getItem(BIOMETRIC_KEY); return raw ? JSON.parse(raw) : null; } catch (e) { return null; }
}
function clearBiometricLock() {
  try { localStorage.removeItem(BIOMETRIC_KEY); } catch (e) {}
}

async function loadFromSupabase() {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/dashboard_data?id=eq.1&select=*`, { headers: sbHeaders() });
  if (!res.ok) throw new Error("Failed to load");
  const rows = await res.json();
  return rows[0] || null;
}

async function saveToSupabase(data) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/dashboard_data?id=eq.1`, {
    method: "PATCH",
    headers: { ...sbHeaders(), Prefer: "return=minimal" },
    body: JSON.stringify({ ...data, updated_at: new Date().toISOString() }),
  });
  if (!res.ok) throw new Error("Failed to save");
}

function migrateRow(row) {
  const migratedEstimates = (row.estimates || seedEstimates).map(e => ({
    createdAt: e.createdAt || e.date || new Date().toISOString(), dueDate: null, lat: null, lng: null, customerId: null, ...e,
  }));
  const migratedInvoices = (row.invoices || seedInvoices).map(i => ({
    createdAt: i.createdAt || i.date || new Date().toISOString(), dueDate: null, lat: null, lng: null, customerId: null, ...i,
  }));
  const migratedTasks = (row.tasks || seedTasks).map(t => ({
    lat: null, lng: null, geofenceMeters: DEFAULT_GEOFENCE_METERS, actualStart: null, actualFinish: null, media: [], employeePay: null, customerId: null, ...t,
  }));
  return {
    leads: row.leads || seedLeads,
    estimates: migratedEstimates,
    invoices: migratedInvoices,
    tasks: migratedTasks,
    employees: row.employees || seedEmployees,
    customers: row.customers || seedCustomers,
  };
}

export default function App() {
  const [session, setSession] = useState(null); // { role: 'owner' } | { role: 'employee', employeeId }
  const [tab, setTab] = useState("overview");
  const [leads, setLeads] = useState(seedLeads);
  const [estimates, setEstimates] = useState(seedEstimates);
  const [invoices, setInvoices] = useState(seedInvoices);
  const [tasks, setTasks] = useState(seedTasks);
  const [employees, setEmployees] = useState(seedEmployees);
  const [customers, setCustomers] = useState(seedCustomers);
  const [draft, setDraft] = useState(null);
  const [openEstimateId, setOpenEstimateId] = useState(null);
  const [openInvoiceId, setOpenInvoiceId] = useState(null);
  const [openCustomerId, setOpenCustomerId] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const [saveError, setSaveError] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [offerBiometric, setOfferBiometric] = useState(false);
  const [lastAuthEmail, setLastAuthEmail] = useState("");
  const [lastRefreshToken, setLastRefreshToken] = useState("");

  // Load saved data once — but only after someone has actually logged in,
  // since the database now requires a real authenticated session to read.
  useEffect(() => {
    if (!session) return;
    setLoaded(false);
    (async () => {
      try {
        const row = await loadFromSupabase();
        if (row) {
          const m = migrateRow(row);
          setLeads(m.leads);
          setEstimates(m.estimates);
          setInvoices(m.invoices);
          setTasks(m.tasks);
          setEmployees(m.employees);
          setCustomers(m.customers);
        }
      } catch (e) {
        setSaveError(true);
      } finally {
        setLoaded(true);
      }
    })();
  }, [session]);

  // Pull the latest data from the database every 20s, and whenever this tab/app
  // comes back into view — this is what makes changes made on one phone (e.g. the
  // owner setting a job's location) show up on another (an employee's phone)
  // without them having to fully close and reopen the app.
  useEffect(() => {
    if (!loaded || !session) return;
    let cancelled = false;
    let lastSynced = JSON.stringify({ leads, estimates, invoices, tasks, employees, customers });
    const refetch = async () => {
      setSyncing(true);
      try {
        const row = await loadFromSupabase();
        if (row && !cancelled) {
          const m = migrateRow(row);
          const key = JSON.stringify(m);
          if (key !== lastSynced) {
            lastSynced = key;
            setLeads(m.leads);
            setEstimates(m.estimates);
            setInvoices(m.invoices);
            setTasks(m.tasks);
            setEmployees(m.employees);
            setCustomers(m.customers);
          }
        }
      } catch (e) {
        // Silent — keep whatever's currently on screen rather than clearing it.
      } finally {
        if (!cancelled) setSyncing(false);
      }
    };
    const iv = setInterval(refetch, 20000);
    const onVisible = () => { if (document.visibilityState === "visible") refetch(); };
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("focus", onVisible);
    return () => {
      cancelled = true;
      clearInterval(iv);
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("focus", onVisible);
    };
  }, [loaded, session]);

  // Persist on every change, once initial load has completed
  useEffect(() => {
    if (!loaded || !session) return;
    saveToSupabase({ leads, estimates, invoices, tasks, employees, customers })
      .then(() => setSaveError(false))
      .catch(() => setSaveError(true));
  }, [loaded, session, leads, estimates, invoices, tasks, employees, customers]);

  const handleLogin = async (email, password) => {
    const { email: authedEmail, refreshToken } = await signInWithPassword(email, password);
    // Fetch the real, current data right now — don't trust whatever was already
    // sitting in memory (which, before any login, is just placeholder seed data
    // and would never match a real employee).
    let matchedEmployee = null;
    try {
      const row = await loadFromSupabase();
      if (row) {
        const m = migrateRow(row);
        setLeads(m.leads);
        setEstimates(m.estimates);
        setInvoices(m.invoices);
        setTasks(m.tasks);
        setEmployees(m.employees);
        setCustomers(m.customers);
        matchedEmployee = m.employees.find(e => (e.email || "").toLowerCase() === authedEmail.toLowerCase());
      }
      setLoaded(true);
    } catch (e) {
      setSaveError(true);
      setLoaded(true);
    }
    if (matchedEmployee) {
      setSession({ role: "employee", employeeId: matchedEmployee.id });
    } else {
      setSession({ role: "owner" });
    }
    setLastAuthEmail(authedEmail);
    setLastRefreshToken(refreshToken);
    // Offer to set up Face ID / fingerprint unlock on this device, once, if it's
    // not already set up here and the device actually supports it.
    if (!loadBiometricLock()) {
      const available = await isBiometricAvailable();
      if (available) setOfferBiometric(true);
    }
  };

  const handleBiometricUnlock = async () => {
    const record = loadBiometricLock();
    if (!record) throw new Error("No Face ID/fingerprint set up on this device yet.");
    const ok = await verifyBiometric(record.credentialId);
    if (!ok) throw new Error("Verification didn't succeed — try again or use your password.");
    const { email: authedEmail } = await refreshSession(record.refreshToken);
    let matchedEmployee = null;
    try {
      const row = await loadFromSupabase();
      if (row) {
        const m = migrateRow(row);
        setLeads(m.leads);
        setEstimates(m.estimates);
        setInvoices(m.invoices);
        setTasks(m.tasks);
        setEmployees(m.employees);
        setCustomers(m.customers);
        matchedEmployee = m.employees.find(e => (e.email || "").toLowerCase() === authedEmail.toLowerCase());
      }
      setLoaded(true);
    } catch (e) {
      setSaveError(true);
      setLoaded(true);
    }
    setSession(matchedEmployee ? { role: "employee", employeeId: matchedEmployee.id } : { role: "owner" });
  };

  const enableBiometric = async () => {
    try {
      const credentialId = await registerBiometric(lastAuthEmail);
      saveBiometricLock({ credentialId, email: lastAuthEmail, refreshToken: lastRefreshToken });
      setOfferBiometric(false);
    } catch (e) {
      setOfferBiometric(false);
    }
  };

  const handleLogout = () => {
    signOutLocal();
    setSession(null);
  };

  if (!session) {
    return <LoginScreen onLogin={handleLogin} onBiometricUnlock={handleBiometricUnlock} />;
  }

  if (!loaded) {
    return (
      <div className="min-h-[640px] flex items-center justify-center" style={{ background: NAVY }}>
        <div className="text-[11px] uppercase tracking-widest font-semibold" style={{ color: "#F3D9AE" }}>Loading your data…</div>
      </div>
    );
  }

  if (offerBiometric) {
    return <BiometricOfferScreen onEnable={enableBiometric} onSkip={() => setOfferBiometric(false)} />;
  }

  if (session.role === "employee") {
    const employee = employees.find(e => e.id === session.employeeId) || employees[0];
    return <EmployeeView employee={employee} tasks={tasks} setTasks={setTasks} onLogout={handleLogout} />;
  }

  const startFromLead = (lead) => {
    setDraft({ customer: lead.name, phone: lead.phone, town: lead.town, address: lead.town, lat: null, lng: null, service: lead.service, email: "", items: [{ desc: lead.service, amount: "" }], depositValue: "", dueDate: "", preferredMethods: [], customerId: null, fromLeadId: lead.id });
    setTab("estimateDraft");
  };
  const startBlank = () => {
    setDraft({ customer: "", phone: "", email: "", address: "", lat: null, lng: null, service: "", items: [{ desc: "", amount: "" }], depositValue: "", dueDate: "", preferredMethods: [], customerId: null });
    setTab("estimateDraft");
  };
  const saveDraft = () => {
    const id = "E-" + (2000 + estimates.length + 32);
    let customerId = draft.customerId || null;

    // No existing customer linked, and the owner wants this saved for reuse — create one now.
    if (!customerId && draft.saveAsCustomer !== false && draft.customer.trim()) {
      customerId = "CUST-" + Date.now();
      const newCustomer = {
        id: customerId, name: draft.customer, phone: draft.phone, email: draft.email,
        addresses: draft.address ? [{ id: "ADDR-" + Date.now(), label: "Main", address: draft.address, lat: draft.lat ?? null, lng: draft.lng ?? null }] : [],
      };
      setCustomers([...customers, newCustomer]);
    } else if (customerId && draft.address) {
      // Existing customer, but this address isn't one of their saved ones yet — add it.
      const c = customers.find(x => x.id === customerId);
      const alreadyHas = c && c.addresses.some(a => a.address === draft.address);
      if (c && !alreadyHas) {
        setCustomers(customers.map(x => x.id === customerId
          ? { ...x, addresses: [...x.addresses, { id: "ADDR-" + Date.now(), label: "New address", address: draft.address, lat: draft.lat ?? null, lng: draft.lng ?? null }] }
          : x));
      }
    }

    setEstimates([{
      id, customer: draft.customer, phone: draft.phone, email: draft.email, address: draft.address, lat: draft.lat ?? null, lng: draft.lng ?? null, service: draft.service,
      status: "Sent", items: draft.items, deposit: { value: draft.depositValue }, preferredMethods: draft.preferredMethods, taskId: null,
      createdAt: new Date().toISOString(), dueDate: draft.dueDate || null, customerId,
    }, ...estimates]);
    if (draft.fromLeadId) setLeads(leads.map(l => l.id === draft.fromLeadId ? { ...l, status: "Converted" } : l));
    setDraft(null);
    setTab("estimates");
  };

  const convertToInvoice = (estimate) => {
    const id = "INV-" + (3300 + invoices.length + 12);
    setInvoices([{
      id, customer: estimate.customer, phone: estimate.phone, email: estimate.email, address: estimate.address, lat: estimate.lat ?? null, lng: estimate.lng ?? null, service: estimate.service,
      date: todayStr(), items: estimate.items, payments: [], preferredMethods: estimate.preferredMethods, taskId: estimate.taskId,
      createdAt: new Date().toISOString(), dueDate: estimate.dueDate || null, customerId: estimate.customerId || null,
    }, ...invoices]);
    setEstimates(estimates.map(e => e.id === estimate.id ? { ...e, status: "Accepted" } : e));
    setOpenEstimateId(null);
    setTab("invoices");
  };

  const addPayment = (invoiceId, amount, method) => {
    setInvoices(invoices.map(inv => inv.id === invoiceId
      ? { ...inv, payments: [...inv.payments, { id: "P-" + Date.now(), amount, method, date: todayStr() }] }
      : inv));
  };

  const updateEstimate = (id, fields) => {
    setEstimates(estimates.map(e => e.id === id ? { ...e, ...fields } : e));
    // Keep any linked job's contact info (and location, if a new address was picked) in sync too —
    // but only touch fields that were actually part of this update.
    const contactFields = ["customer", "phone", "address", "service"].filter(k => fields[k] !== undefined);
    if (contactFields.length > 0 || fields.lat != null) {
      setTasks(tasks.map(t => t.sourceId === id ? {
        ...t,
        ...Object.fromEntries(contactFields.map(k => [k, fields[k]])),
        ...(fields.lat != null ? { lat: fields.lat, lng: fields.lng } : {}),
      } : t));
    }
  };
  const updateInvoice = (id, fields) => {
    setInvoices(invoices.map(i => i.id === id ? { ...i, ...fields } : i));
    const contactFields = ["customer", "phone", "address", "service"].filter(k => fields[k] !== undefined);
    if (contactFields.length > 0 || fields.lat != null) {
      setTasks(tasks.map(t => t.sourceId === id ? {
        ...t,
        ...Object.fromEntries(contactFields.map(k => [k, fields[k]])),
        ...(fields.lat != null ? { lat: fields.lat, lng: fields.lng } : {}),
      } : t));
    }
  };

  const createTask = (source, start, finish, coords, assignedTo, employeePay, sourceType) => {
    const id = "T-" + Date.now();
    // Prefer a location captured manually at the job site; otherwise fall back
    // to coordinates already picked via address autocomplete on the estimate/invoice.
    const lat = coords?.lat ?? source.lat ?? null;
    const lng = coords?.lng ?? source.lng ?? null;
    const task = {
      id, customer: source.customer, phone: source.phone, address: source.address, service: source.service,
      customerId: source.customerId || null,
      start, finish, status: "Scheduled", sourceId: source.id, sourceType,
      assignedTo: assignedTo || null, employeePay: employeePay || null, materials: [], notes: [],
      lat, lng, geofenceMeters: DEFAULT_GEOFENCE_METERS,
      actualStart: null, actualFinish: null, media: [],
    };
    setTasks([task, ...tasks]);
    if (sourceType === "estimate") setEstimates(estimates.map(e => e.id === source.id ? { ...e, taskId: id } : e));
    else setInvoices(invoices.map(i => i.id === source.id ? { ...i, taskId: id } : i));
  };

  const addEmployee = (name, email) => {
    const id = "EMP-" + (employees.length + 1);
    setEmployees([...employees, { id, name, email: email || "" }]);
  };
  const updateEmployeeEmail = (id, email) => {
    setEmployees(employees.map(e => e.id === id ? { ...e, email } : e));
  };

  const addCustomer = ({ name, phone, email, address, lat, lng }) => {
    const id = "CUST-" + Date.now();
    const addresses = address ? [{ id: "ADDR-" + Date.now(), label: "Main", address, lat: lat ?? null, lng: lng ?? null }] : [];
    setCustomers([{ id, name, phone, email, addresses }, ...customers]);
  };
  const updateCustomer = (id, fields) => setCustomers(customers.map(c => c.id === id ? { ...c, ...fields } : c));
  const addAddressToCustomer = (customerId, { label, address, lat, lng }) => {
    setCustomers(customers.map(c => c.id === customerId
      ? { ...c, addresses: [...c.addresses, { id: "ADDR-" + Date.now(), label, address, lat, lng }] }
      : c));
  };
  const deleteCustomerAddress = (customerId, addressId) => {
    setCustomers(customers.map(c => c.id === customerId ? { ...c, addresses: c.addresses.filter(a => a.id !== addressId) } : c));
  };
  const deleteCustomer = (id) => {
    setCustomers(customers.filter(c => c.id !== id));
    setOpenCustomerId(null);
  };
  const deleteEstimate = (id) => {
    setEstimates(estimates.filter(e => e.id !== id));
    setOpenEstimateId(null);
  };
  const deleteInvoice = (id) => {
    setInvoices(invoices.filter(i => i.id !== id));
    setOpenInvoiceId(null);
  };
  const deleteTask = (id) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const openEstimate = estimates.find(e => e.id === openEstimateId);
  const openInvoice = invoices.find(i => i.id === openInvoiceId);
  const openCustomer = customers.find(c => c.id === openCustomerId);
  const taskFor = (sourceId) => tasks.find(t => t.sourceId === sourceId);

  return (
    <div className="max-w-sm mx-auto min-h-[640px] flex flex-col" style={{ background: PAPER, fontFamily: "system-ui, sans-serif" }}>
      {tab === "overview" && (
        <TopBar
          title="House Fixed · Console"
          right={
            <div className="flex items-center gap-3">
              <LanguageToggle dark />
              <span className="text-[10px] font-mono uppercase tracking-wider" style={{ color: saveError ? "#F5A3A3" : "#8FA1A6" }}>
                {saveError ? t("offlineNotSaved") : syncing ? t("syncingLabel") : t("synced")}
              </span>
              <button onClick={handleLogout} className="text-white/80"><LogOut size={18} /></button>
            </div>
          }
        />
      )}
      {tab === "leads" && <TopBar title="Leads" />}
      {tab === "customers" && !openCustomerId && <TopBar title="Customers" />}
      {tab === "customers" && openCustomerId && <TopBar title={openCustomer?.name || "Customer"} onBack={() => setOpenCustomerId(null)} />}
      {tab === "estimates" && !openEstimateId && <TopBar title="Estimates" />}
      {tab === "estimates" && openEstimateId && <TopBar title={openEstimateId} onBack={() => setOpenEstimateId(null)} />}
      {tab === "invoices" && !openInvoiceId && <TopBar title="Invoices" />}
      {tab === "invoices" && openInvoiceId && <TopBar title={openInvoiceId} onBack={() => setOpenInvoiceId(null)} />}
      {tab === "jobs" && <TopBar title="Jobs" />}
      {tab === "estimateDraft" && <TopBar title="New estimate" onBack={() => setTab(draft?.fromLeadId ? "leads" : "estimates")} />}

      <div className="flex-1 overflow-y-auto">
        {tab === "overview" && <OverviewTab leads={leads} estimates={estimates} invoices={invoices} tasks={tasks} />}
        {tab === "leads" && <LeadsTab leads={leads} setLeads={setLeads} onConvert={startFromLead} />}
        {tab === "customers" && !openCustomerId && <CustomersTab customers={customers} onAdd={addCustomer} onOpen={(id) => setOpenCustomerId(id)} />}
        {tab === "customers" && openCustomerId && openCustomer && (
          <CustomerDetail customer={openCustomer} onUpdate={updateCustomer} onAddAddress={addAddressToCustomer} onDeleteAddress={deleteCustomerAddress} onDelete={deleteCustomer}
            estimates={estimates} invoices={invoices} tasks={tasks}
            onOpenEstimate={(id) => { setOpenCustomerId(null); setOpenEstimateId(id); setTab("estimates"); }}
            onOpenInvoice={(id) => { setOpenCustomerId(null); setOpenInvoiceId(id); setTab("invoices"); }} />
        )}
        {tab === "estimates" && !openEstimateId && <EstimatesTab estimates={estimates} onNewFromScratch={startBlank} onOpen={(e) => setOpenEstimateId(e.id)} />}
        {tab === "estimates" && openEstimateId && openEstimate && (
          <EstimateDetail estimate={openEstimate} onConvertToInvoice={convertToInvoice} onUpdate={updateEstimate} employees={employees} onDelete={deleteEstimate}
            onCreateTask={(src, start, finish, coords, assignedTo, employeePay) => createTask(src, start, finish, coords, assignedTo, employeePay, "estimate")} task={taskFor(openEstimate.id)} />
        )}
        {tab === "invoices" && !openInvoiceId && <InvoicesTab invoices={invoices} onOpen={(inv) => setOpenInvoiceId(inv.id)} />}
        {tab === "invoices" && openInvoiceId && openInvoice && (
          <InvoiceDetail invoice={openInvoice} onAddPayment={addPayment} onUpdate={updateInvoice} employees={employees} onDelete={deleteInvoice}
            onCreateTask={(src, start, finish, coords, assignedTo, employeePay) => createTask(src, start, finish, coords, assignedTo, employeePay, "invoice")} task={taskFor(openInvoice.id)} />
        )}
        {tab === "jobs" && <JobsTab tasks={tasks} setTasks={setTasks} employees={employees} onAddEmployee={addEmployee} onUpdateEmployeeEmail={updateEmployeeEmail} onDeleteTask={deleteTask} />}
        {tab === "estimateDraft" && draft && (
          <EstimateBuilder draft={draft} setDraft={setDraft} onSave={saveDraft} onCancel={() => setTab(draft.fromLeadId ? "leads" : "estimates")} customers={customers} />
        )}
      </div>

      {tab !== "estimateDraft" && !openEstimateId && !openInvoiceId && !openCustomerId && <BottomNav active={tab} setActive={setTab} />}
    </div>
  );
}
